@Service
public class InventoryService {
    private final InventoryRepository inventoryRepo;

    @Transactional  // Backend ensures data consistency
    public synchronized void reserveItem(Long productId, int quantity) {
        var inventory = inventoryRepo.findById(productId)
            .orElseThrow(() -> new ProductNotFoundException(productId));

        // Backend problem: prevent overselling when concurrent requests happen
        if (inventory.getAvailable() < quantity) {
            throw new InsufficientStockException(
                "Only " + inventory.getAvailable() + " items available"
            );
        }

        // Update must be atomic to prevent race conditions
        inventory.setAvailable(inventory.getAvailable() - quantity);
        inventoryRepo.save(inventory);

        // This is backend work: correctness over appearance
    }
}
