@Service
public class PaymentService {
    public PaymentResult processPayment(PaymentRequest request) {
        // Compiler enforces correct types
        if (request.amount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
        }

        // IDE autocomplete knows all fields and types
        var userId = request.userId();  // Long, not String
        var amount = request.amount();  // BigDecimal, precise for money

        // Type safety prevents runtime surprises
        return new PaymentResult(userId, amount, "SUCCESS");
    }
}

// In Python/Node, request could be any dict/object
// Type errors appear at runtime when real money is involved
