// Example distributed system learning project - Order Service calling Inventory Service

@Service
public class OrderService {
    private final RestTemplate restTemplate;
    private final CircuitBreakerFactory circuitBreakerFactory;

    public Order createOrder(OrderRequest request) {
        // Skill gap 1: Circuit breaker for fault tolerance
        var circuitBreaker = circuitBreakerFactory.create("inventory-service");

        // Skill gap 2: Inter-service communication with fallback
        Boolean inventoryAvailable = circuitBreaker.run(
            () -> restTemplate.postForObject(
                "http://inventory-service/check",
                request.getItems(),
                Boolean.class
            ),
            throwable -> false  // Fallback if inventory service is down
        );

        if (!inventoryAvailable) {
            throw new OutOfStockException();
        }

        // Skill gap 3: Eventual consistency via messaging
        var order = new Order(request.getUserId(), request.getItems());
        orderRepository.save(order);

        // Publish event - inventory updated asynchronously
        rabbitTemplate.convertAndSend("orders", "order.created", order);
        return order;
    }
}
